package app.space.notes.runtime;

import android.content.Context;
import android.view.*;
import android.widget.*;
import androidx.recyclerview.widget.*;
import org.json.JSONObject;
import java.text.*;
import java.util.*;

/** Parsed app-private records only: no system logcat, uploads or note-content collection. */
final class DiagnosticLogView extends LinearLayout implements AutoCloseable {
    private final NotesDesign design;private final NotesHost host;private final RecyclerView list;private final TextView status;private final Set<String> levels=new HashSet<>(Arrays.asList("DEBUG","INFO","WARN","ERROR"));
    private long duration=Long.MAX_VALUE,from=Long.MIN_VALUE,to;private boolean custom,closed;private int generation;private List<JSONObject> records=Collections.emptyList();
    DiagnosticLogView(Context context,NotesDesign design,NotesHost host){
        super(context);this.design=design;this.host=host;setOrientation(VERTICAL);
        LinearLayout tools=new LinearLayout(context);if(context.getResources().getConfiguration().fontScale>1.3f)tools.setOrientation(VERTICAL);
        tools.addView(design.textAction("Time range",this::timeRange));tools.addView(design.textAction("Levels",this::chooseLevels));tools.addView(design.textAction("Refresh",this::refresh));addView(tools);
        status=design.label("",13,design.muted);addView(status);addView(design.textAction("Save filtered logs",()->host.exportDiagnosticRange(from,to,new HashSet<>(levels))));
        list=new RecyclerView(context);list.setLayoutManager(new LinearLayoutManager(context));addView(list,new LayoutParams(-1,0,1));refresh();
    }
    private void refresh(){if(!custom){to=System.currentTimeMillis();from=duration==Long.MAX_VALUE?Long.MIN_VALUE:to-duration;}int ticket=++generation;status.setText("Reading local logs…");Diagnostics.read(from,to,levels,snapshot->post(()->{if(closed || ticket!=generation)return;records=snapshot.rows;list.setAdapter(new LogAdapter());String range=from==Long.MIN_VALUE?"All retained times":DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new Date(from))+" — "+DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new Date(to));status.setText(snapshot.total+" matching records · newest first\n"+range+" · "+TimeZone.getDefault().getID()+(snapshot.total>5000?"\nShowing/saving newest 5,000; narrow filters for more":"")+(snapshot.total==0?"\nNo matching records. Enable collection before reproducing an issue.":""));}),error->post(()->{if(!closed && ticket==generation)status.setText("Logs could not be read; existing files and notes were retained.");}));}
    private void timeRange(){String[] labels={"All retained times","Last 15 minutes","Last hour","Last 24 hours","Last 7 days","Custom local date/time range"};long[] durations={Long.MAX_VALUE,15*60*1000L,60*60*1000L,24*60*60*1000L,7*24*60*60*1000L};design.show(new android.app.AlertDialog.Builder(getContext()).setTitle("Diagnostic time range").setItems(labels,(d,index)->{if(index==5){customRange();return;}custom=false;duration=durations[index];refresh();}).setNegativeButton("Cancel",null).create());}
    private void customRange(){LinearLayout fields=new LinearLayout(getContext());fields.setOrientation(VERTICAL);fields.setPadding(design.dp(16),design.dp(8),design.dp(16),design.dp(8));fields.addView(design.label("Local time: "+TimeZone.getDefault().getID()+"\nyyyy-MM-dd HH:mm",14,design.ink));SimpleDateFormat format=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT);format.setLenient(false);EditText start=new EditText(getContext()),end=new EditText(getContext());start.setHint("From (inclusive)");end.setHint("To (inclusive minute)");start.setText(format.format(new Date(from==Long.MIN_VALUE?System.currentTimeMillis()-60*60*1000L:from)));end.setText(format.format(new Date(to)));design.entry(start,16);design.entry(end,16);fields.addView(start);fields.addView(end);TextView error=design.label("",13,design.muted);fields.addView(error);android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(getContext()).setTitle("Custom diagnostic range").setView(fields).setPositiveButton("Apply",null).setNegativeButton("Cancel",null).create();design.show(dialog);dialog.getButton(-1).setOnClickListener(v->{try{String a=start.getText().toString().trim(),b=end.getText().toString().trim();ParsePosition pa=new ParsePosition(0),pb=new ParsePosition(0);Date first=format.parse(a,pa),last=format.parse(b,pb);if(first==null || last==null || pa.getIndex()!=a.length() || pb.getIndex()!=b.length() || last.before(first))throw new IllegalArgumentException();from=first.getTime();to=last.getTime()+59999;custom=true;dialog.dismiss();refresh();}catch(Exception invalid){error.setText("Use valid yyyy-MM-dd HH:mm values, with end not before start.");}});}
    private void chooseLevels(){String[] labels={"DEBUG","INFO","WARN","ERROR"};boolean[] checked=new boolean[labels.length];for(int i=0;i<labels.length;i++)checked[i]=levels.contains(labels[i]);design.show(new android.app.AlertDialog.Builder(getContext()).setTitle("Diagnostic levels").setMultiChoiceItems(labels,checked,(d,index,value)->checked[index]=value).setPositiveButton("Apply",(d,w)->{levels.clear();for(int i=0;i<labels.length;i++)if(checked[i])levels.add(labels[i]);refresh();}).setNegativeButton("Cancel",null).create());}
    private void showRecord(JSONObject record){String value;try{value=record.toString(2);}catch(Exception invalid){value=record.toString();}TextView text=design.label(value,15,design.ink);text.setTextIsSelectable(true);text.setPadding(design.dp(16),design.dp(12),design.dp(16),design.dp(12));ScrollView scroll=new ScrollView(getContext());scroll.addView(text);design.show(new android.app.AlertDialog.Builder(getContext()).setTitle("Diagnostic record").setView(scroll).setPositiveButton("Close",null).create());}
    private final class LogAdapter extends RecyclerView.Adapter<RecyclerView.ViewHolder>{
        @Override public int getItemCount(){return records.size();}
        @Override public RecyclerView.ViewHolder onCreateViewHolder(ViewGroup parent,int type){TextView text=design.label("",14,design.ink);text.setPadding(design.dp(8),design.dp(8),design.dp(8),design.dp(8));text.setMinHeight(design.dp(48));text.setMaxLines(4);text.setEllipsize(android.text.TextUtils.TruncateAt.END);text.setLayoutParams(new RecyclerView.LayoutParams(-1,-2));return new RecyclerView.ViewHolder(text){};}
        @Override public void onBindViewHolder(RecyclerView.ViewHolder holder,int position){JSONObject row=records.get(position);String detail=row.optString("detail",row.optString("stack_no_messages",""));if(detail.length()>500)detail=detail.substring(0,500)+"…";TextView text=(TextView)holder.itemView;text.setText(DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.MEDIUM).format(new Date(row.optLong("at_ms")))+" · "+row.optString("level",Diagnostics.level(row.optString("event")))+"\n"+row.optString("event")+"\n"+detail);text.setOnClickListener(v->showRecord(row));}
    }
    @Override public void close(){closed=true;generation++;list.setAdapter(null);records=Collections.emptyList();}
}
